def section(id,title,body,cls=''):
 return f'<section class="band {cls}" data-section="{id}" data-component="content-band" aria-labelledby="{id}-title"><div class="wrap"><h2 id="{id}-title">{title}</h2>{body}</div></section>'
def card(id,title,body,link=None,label=None):
 return f'<article class="card" data-section="{id}" data-component="feature-card"><h3>{title}</h3><p>{body}</p>'+ (f'<a class="text-link" href="{link}">{label or "Explore "+title} <span aria-hidden="true">→</span></a>' if link else '')+'</article>'
def details(id,title,body):
 return f'<details data-section="{id}" data-component="accordion"><summary>{title}</summary><div class="answer">{body}</div></details>'
def hero(eyebrow,title,body,cta='',art=False):
 return f'<section class="hero {"hero-art" if art else ""}" data-section="page-introduction" data-component="page-hero"><div class="wrap hero-grid"><div><p class="eyebrow">{eyebrow}</p><h1>{title}</h1><p class="intro">{body}</p>{cta}</div>'+('<img src="assets/community.svg" alt="Illustration of a small home among forested hills" width="760" height="560">' if art else '')+'</div></section>'
btn=lambda href,text:f'<a class="button" href="{href}">{text}</a>'
